"""Distinct, editable laboratory specifications for lessons 26a through 46.

Solutions are source-side verification assets, not learner notebook cells.
"""

from textwrap import dedent, indent


def _check(body, repair=False):
    function = "test_repair" if repair else "test_exercise"
    flag = "repair_complete" if repair else "exercise_complete"
    return (f"def {function}():\n" + indent(dedent(body).strip(), "    ")
            + f"\n\n{flag} = {function}()\n"
            + f'print("PASS" if {flag} else "INCOMPLETE: complete the TODO first")\n')


def _lab(*, torch_setup=True, **fields):
    fields = {name: dedent(value).strip() for name, value in fields.items()}
    imports = ("import math\nimport torch\ntorch.set_num_threads(1)\n"
               "torch.manual_seed(17)\n") if torch_setup else "import math\n"
    fields["setup"] = imports + fields["setup"]
    fields["check"] = _check(fields.pop("checks"))
    fields["fix_check"] = _check(fields.pop("fix_checks"), repair=True)
    return fields


