        checks="result = manual_ffn(ffn,x)\nif result is None: return False\ntorch.testing.assert_close(result,ffn(x))\ntorch.testing.assert_close(result[:,0],result[:,1])\nchanged = x.clone(); changed[:,2] += 20\ntorch.testing.assert_close(manual_ffn(ffn,changed)[:,:2],result[:,:2])\nother = torch.randn(1,5,4)\ntorch.testing.assert_close(manual_ffn(ffn,other),ffn(other))\nreturn True",
        solution="def manual_ffn(ffn, x):\n    first,last = ffn.layers[0],ffn.layers[2]\n    hidden = x@first.weight.T + first.bias\n    return F.gelu(hidden)@last.weight.T + last.bias",
        vary="فقط موقعیت آخر را به اندازهٔ ۱۰ افزایش دهید. اختلاف خروجی هر موقعیت را جدا چاپ کنید؛ صفرهای سایر موقعیت‌ها مهم‌تر از مقدار عددی اختلاف آخرند.",
