        setup="source = torch.tensor([[1.,0.],[0.,1.],[1.,1.],[-1.,0.],[0.,-1.]])\ntarget = torch.tensor([[1.,0.],[0.,1.],[1.,1.]])\nprint('source/target lengths:',len(source),len(target))",
